GITHUB_ISSUE_URL = re.compile(
    r"https://github\.com/(?P<owner>[^/]+)/(?P<repository>[^/]+)/issues/(?P<number>\d+)"
)


def link_published_issues(apps, schema_editor):
    """
    Turn the GitHub issue recorded for each published issue into a linked item.
    Ignoring the events, those will be captured back from GitHub in the future.
    """
    NixpkgsEvent = apps.get_model("shared", "NixpkgsEvent")
    NixpkgsIssue = apps.get_model("shared", "NixpkgsIssue")
    GitHubItem = apps.get_model("shared", "GitHubItem")
    for event in NixpkgsEvent.objects.all():
        match = GITHUB_ISSUE_URL.fullmatch(event.url)
        if match is None:
            raise ValueError(f"Not a GitHub issue URL: {event.url}")
        item, _ = GitHubItem.objects.get_or_create(
            owner=match["owner"],
            repository=match["repository"],
            number=int(match["number"]),
            defaults={"kind": "Issue"},
        )
        NixpkgsIssue.github_items.through.objects.get_or_create(
            nixpkgsissue_id=event.issue_id, githubitem_id=item.id
        )


